"""Shell-command permissions for agent sessions, generated by `hive init`.

Hive runs on Windows, macOS and Linux, and agents use POSIX shells (bash; Git Bash on Windows),
PowerShell and cmd.exe, so every rule here covers all three.

Three tiers, so the fleet needs as little human intervention as possible while staying safe:

* **allow**: run directly (reading, tests, building, ordinary git history work).
* **approval**: dangerous git operations, recursive/forced deletes, elevation and similar. A
  worker's CLI blocks them; the worker calls `request_approval`, the orchestrator decides, and
  the Hive daemon runs the exact approved command once in the worker's worktree. The
  orchestrator's own session is interactive, so for it these commands prompt the user.
* **forbidden**: Hive's user/admin commands. Never run by an agent, approval or not.

Two layers enforce this:
1. Per-CLI permission files (`--settings` / `--policy` / Codex `.rules`) use command
   *prefixes*: "git diff" -> Claude Bash(git diff *), PowerShell(git diff *); Gemini
   commandPrefix; Codex prefix_rule(pattern=["git", "diff"]).
2. Hive's PreToolUse hook parses the command itself: it splits compound commands, unwraps
   nested shells (`bash -c`, `cmd /c`, `powershell -Command`, including -EncodedCommand),
   normalises program names (`C:\\...\\git.exe` -> git) and recognises dangerous *flags in any
   position* (`Remove-Item x -Recurse`, `del /s /q`, `rm -fr`). The hook is authoritative;
   prefixes alone can't express flags that come after a path.

Neither layer is a security boundary against a determined agent (the CLIs' docs say the same
of their rules). The hard protections are server-side checks and the daemon's checks before it
runs an approved command.
"""

from __future__ import annotations

import base64
import binascii
import json
import re

ROLE_CLASSES = ("orchestrator", "worker")
PRESETS = ("standard", "strict", "none")

# Inspecting the repository and the system; safe for every role. POSIX, PowerShell and cmd.
READ_ONLY = [
    "git status", "git diff", "git log", "git show", "git branch", "git rev-parse",
    "git ls-files", "git blame", "git grep", "git fetch", "git remote -v", "git describe",
    "git shortlog", "git merge-base", "git cat-file", "git worktree list", "git reflog",
    "git --version",
    # POSIX (most also work as PowerShell aliases)
    "ls", "cat", "head", "tail", "wc", "grep", "rg", "find", "tree", "pwd", "echo", "which",
    "stat", "file", "du", "diff", "sort", "uniq", "cut",
    # cmd.exe
    "dir", "type", "where", "findstr", "ver",
    # PowerShell
    "Get-ChildItem", "gci", "Get-Content", "gc", "Select-String", "sls", "Get-Location",
    "Get-Item", "Test-Path", "Resolve-Path", "Get-Command", "Get-FileHash", "Measure-Object",
    "Compare-Object", "Write-Output", "Write-Host",
    "python --version", "python3 --version", "py --version", "node --version",
    "npm --version", "dotnet --version",
]

# Running a project's tests and static checks; every role (the orchestrator verifies reports
# and the reviewer verifies work by running them).
TESTS = [
    "pytest", "python -m pytest", "python3 -m pytest", "py -m pytest", "uv run pytest",
    "npm test", "npm run test", "yarn test", "pnpm test", "cargo test", "cargo check",
    "go test", "go vet", "make test", "make check", "ruff check", "mypy", "npx tsc --noEmit",
    "tsc --noEmit", "dotnet test", "mvn test", "gradle test", "gradlew test",
]

# Building, running and managing files: needed by coding roles. Interpreters and task runners
# can run arbitrary code, which is why the "strict" preset leaves this list out. Dangerous
# forms (recursive/forced deletes etc.) are caught by the approval tier regardless.
BUILD = [
    "python", "python3", "py", "uv run", "uv sync", "node", "npm run", "npm ci", "npm install",
    "yarn", "pnpm", "npx", "cargo build", "cargo run", "cargo fmt", "cargo clippy", "go build",
    "go run", "go fmt", "make", "cmake", "ninja", "dotnet build", "dotnet run", "msbuild",
    "mvn", "gradle", "gradlew", "ruff", "black", "prettier", "eslint",
    # POSIX file operations
    "mkdir", "touch", "cp", "mv", "rm", "rmdir",
    # cmd.exe file operations
    "md", "copy", "move", "ren", "del", "erase",
    # PowerShell file operations
    "New-Item", "Copy-Item", "Move-Item", "Rename-Item", "Remove-Item", "Set-Content",
    "Add-Content", "Out-File",
]

# Ordinary, recoverable git history work in the agent's own branch.
GIT_HISTORY = [
    "git add", "git commit", "git merge", "git rebase", "git cherry-pick", "git revert",
    "git checkout", "git switch", "git restore", "git stash", "git tag", "git mv", "git rm",
    "git am", "git apply",
]

# Dangerous: publishes, discards or rewrites history, deletes recursively or forcibly, elevates
# privileges or touches the machine itself. Workers need the orchestrator's approval; the
# orchestrator's own (interactive) session asks the user. Delete/elevation/permission flags
# are also detected in any position by `dangerous()`; these prefixes are their common forms
# for the CLIs' own rule engines.
APPROVAL = [
    # git
    "git push", "git reset --hard", "git clean", "git checkout --", "git checkout -f",
    "git restore --source", "git branch -D", "git branch --delete --force", "git update-ref",
    "git filter-branch", "git filter-repo", "git reflog expire", "git gc --prune",
    "git stash drop", "git stash clear", "git rebase --root",
    # recursive / forced deletes: POSIX, cmd.exe, PowerShell
    "rm -r", "rm -R", "rm -rf", "rm -fr", "rm -Rf", "rm -fR", "rm -f", "rm --recursive",
    "rm --force", "rm -Recurse", "rm -Force",
    "del /s", "del /q", "del /f", "erase /s", "erase /q", "rd /s", "rmdir /s", "rmdir -Recurse",
    "Remove-Item -Recurse", "Remove-Item -Force", "Remove-Item -r", "ri -r", "ri -Recurse",
    # elevation and system changes
    "sudo", "su", "doas", "runas", "gsudo", "Start-Process -Verb RunAs",
    "chmod -R", "chown -R", "takeown", "Set-Acl",  # icacls changes: see dangerous()
    "dd", "mkfs", "shred", "format", "diskpart", "Format-Volume", "Clear-Disk", "reg delete",
    "Remove-ItemProperty", "shutdown", "Stop-Computer", "Restart-Computer",
    "Set-ExecutionPolicy",
]

# Never for agents, even with approval: an agent must not answer decisions, speak as the user
# or reconfigure Hive, even on a machine where the user is logged in as admin.
FORBIDDEN = [
    "hive decide", "hive admin", "hive start", "hive say", "hive pause", "hive resume",
    "hive reset", "hive init", "hive join", "hive up",
]


def _norm(cmds) -> list[str]:
    out = []
    for c in cmds or []:
        c = " ".join(str(c).split())
        if c.endswith(" *"):
            c = c[:-2]
        if c.endswith(":*"):
            c = c[:-2]
        if not c or "*" in c:
            raise ValueError(f"[permissions] entries are command prefixes without wildcards: "
                             f"{c!r}")
        if c not in out:
            out.append(c)
    return out


def build_rules(cfg: dict) -> dict[str, dict[str, list[str]]]:
    """allow / approval / forbidden prefixes per role class from hive.toml [permissions]."""
    perms = cfg.get("permissions", {}) or {}
    preset = perms.get("preset", "standard")
    if preset not in PRESETS:
        raise ValueError(f"[permissions] preset must be one of {PRESETS}")
    checks = _norm(cfg.get("integration", {}).get("checks", []))
    extra_allow = _norm(perms.get("allow"))
    extra_approval = _norm(perms.get("approval"))
    extra_deny = _norm(perms.get("deny"))
    forbidden = list(dict.fromkeys(FORBIDDEN + extra_deny))
    approval = [a for a in dict.fromkeys(APPROVAL + extra_approval) if a not in forbidden]
    rules = {}
    for cls in ROLE_CLASSES:
        allow = ([] if preset == "none" else READ_ONLY + TESTS) + checks + extra_allow
        if cls == "worker" and preset != "none":
            allow += GIT_HISTORY
            if preset == "standard":
                allow += BUILD
        rules[cls] = {"allow": [a for a in dict.fromkeys(allow)
                                if a not in forbidden and a not in approval],
                      "approval": list(approval), "forbidden": list(forbidden)}
    return rules


def role_class(roles: list[str]) -> str:
    return "orchestrator" if "orchestrator" in roles else "worker"


# ---------------------------------------------------------------------- parsing

# Statement and pipeline separators of bash, cmd.exe and PowerShell; grouping characters
# (subshells, $( ), script blocks) also start a new simple command. Only outside quotes.
_SEPARATOR_CHARS = set(";|&\n\r(){}")
_QUOTES = "'\""


def _tokenize(command: str) -> list[list[str]]:
    """Quote-aware split into simple commands (lists of words, quotes removed). Separators
    and spaces inside '…' or "…" are literal, so `git commit -m "a; rm -rf b"` is one command
    and `bash -c "x && y"` keeps its inner command as one word."""
    parts: list[list[str]] = []
    words: list[str] = []
    word, quote, has_word = [], None, False

    def end_word():
        nonlocal word, has_word
        if has_word:
            words.append("".join(word))
        word, has_word = [], False

    def end_part():
        nonlocal words
        end_word()
        if words:
            parts.append(words)
        words = []

    for ch in command or "":
        if quote:
            if ch == quote:
                quote = None
            else:
                word.append(ch)
            continue
        if ch in _QUOTES:
            quote, has_word = ch, True
        elif ch in _SEPARATOR_CHARS:
            end_part()
        elif ch.isspace():
            end_word()
        else:
            word.append(ch)
            has_word = True
    end_part()
    return parts


_WRAPPERS = {"timeout", "time", "nice", "nohup", "stdbuf", "command", "builtin", "noglob",
             "exec", "env", "call", "start", "invoke-expression", "iex"}
_ASSIGN = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*=\S*$")
_EXTENSIONS = (".exe", ".cmd", ".bat", ".com", ".ps1", ".sh")
_POSIX_SHELLS = {"bash", "sh", "zsh", "dash", "ksh", "fish"}
_POWERSHELLS = {"powershell", "pwsh"}


def program(word: str) -> str:
    """Normalise a program word: strip quotes and directories and Windows extensions, lower
    case. `"C:\\Program Files\\Git\\cmd\\git.exe"` -> `git`, `./gradlew.bat` -> `gradlew`."""
    w = word.strip("'\"`").replace("\\", "/").rsplit("/", 1)[-1].lower()
    for ext in _EXTENSIONS:
        if w.endswith(ext):
            return w[: -len(ext)]
    return w


def _nested(words: list[str]) -> str | None:
    """The inner command of `bash -c "…"`, `cmd /c …`, `powershell -Command …` or
    `pwsh -EncodedCommand <base64>`; None for anything else."""
    prog, args = words[0], words[1:]
    lowered = [a.lower() for a in args]
    if prog in _POSIX_SHELLS and "-c" in lowered:
        return " ".join(_requote(args[lowered.index("-c") + 1:]))
    if prog == "cmd":
        for i, a in enumerate(lowered):
            if a in ("/c", "/k"):
                return " ".join(_requote(args[i + 1:]))
            if a.startswith(("/c", "/k")) and len(a) > 2:  # cmd /cgit status
                return " ".join(_requote([args[i][2:], *args[i + 1:]]))
    if prog in _POWERSHELLS:
        for i, a in enumerate(lowered):
            if a.startswith("-e") and len(a) >= 2 and "encodedcommand".startswith(a[1:]) \
                    and i + 1 < len(args):
                try:
                    return base64.b64decode(args[i + 1]).decode("utf-16-le")
                except (binascii.Error, UnicodeDecodeError, ValueError):
                    return None
            if a.startswith("-") and len(a) >= 2 and "command".startswith(a[1:]):
                return " ".join(_requote(args[i + 1:]))
    return None


def _requote(words: list[str]) -> list[str]:
    """Re-join words for re-parsing: a single word holding a whole inner command (the usual
    `bash -c "a && b"`) is returned as is; other words containing spaces are quoted."""
    if len(words) == 1:
        return words
    return [f'"{w}"' if any(c.isspace() for c in w) else w for w in words]


def _split(command: str, depth: int = 0) -> list[list[str]]:
    """Simple commands as word lists; program normalised, quotes stripped, nested shells
    unwrapped (one entry for the shell call itself, plus its inner commands)."""
    out: list[list[str]] = []
    for words in _tokenize(command):
        while words and (_ASSIGN.match(words[0]) or program(words[0]) in _WRAPPERS
                         or words[0] in ("$", "@")):
            words.pop(0)
            if words and words[0].lstrip("-").isdigit():  # e.g. `timeout 30 cmd`
                words.pop(0)
        if not words:
            continue
        words[0] = program(words[0])
        if words[0] == "git":
            words = ["git", *_strip_git_globals(words[1:])]
        out.append(words)
        if depth >= 4:
            continue
        inner = _nested(words)
        if inner:
            out.extend(_split(inner, depth + 1))
        if words[0] == "xargs":
            rest = _xargs_command(words[1:])
            if rest:
                out.extend(_split(" ".join(_requote(rest)), depth + 1))
    return out


# git options that come before the subcommand; those listed here take a separate value.
_GIT_VALUE_OPTS = {"-c", "-C", "--git-dir", "--work-tree", "--namespace", "--config-env",
                   "--super-prefix"}


def _strip_git_globals(args: list[str]) -> list[str]:
    """`git -C dir -c k=v --no-pager push …` -> `push …`, so rules see the subcommand."""
    i = 0
    while i < len(args) and args[i].startswith("-"):
        i += 2 if args[i] in _GIT_VALUE_OPTS else 1
    return args[i:]


# xargs options that take a separate value.
_XARGS_VALUE_OPTS = {"-I", "-L", "-l", "-n", "-P", "-s", "-d", "-E", "-e", "-a",
                     "--arg-file", "--delimiter", "--max-args", "--max-lines",
                     "--max-procs", "--max-chars", "--eof", "--replace", "--process-slot-var"}


def _xargs_command(args: list[str]) -> list[str]:
    """The command xargs runs: `xargs -0 -n1 rm -f` -> `rm -f`."""
    i = 0
    while i < len(args) and args[i].startswith("-"):
        i += 2 if args[i] in _XARGS_VALUE_OPTS else 1
    return args[i:]


def subcommands(command: str) -> list[str]:
    """Split a command into simple commands (normalised, nested shells unwrapped)."""
    return [" ".join(w) for w in _split(command)]


def matches(command: str, prefixes: list[str]) -> str | None:
    """The first prefix matching any simple command inside `command`, or None. Matching is
    case-insensitive (PowerShell and cmd.exe are) and on whole words."""
    for words in _split(command):
        low = " ".join(words).lower()
        for p in prefixes:
            pw = p.split()
            pl = " ".join([program(pw[0])] + pw[1:]).lower()
            if low == pl or low.startswith(pl + " "):
                return p
    return None


# ---------------------------------------------------------------------- dangerous flags

_DELETE_PROGRAMS = {"rm", "del", "erase", "rd", "rmdir", "ri", "remove-item", "rimraf"}


def _ps_param(arg: str, *names: str, minimum: int = 1) -> bool:
    """PowerShell parameter `arg` (e.g. -Rec, -Force:$true) abbreviates one of `names`."""
    if not arg.startswith("-") or arg.startswith("--"):
        return False
    name = arg[1:].split(":", 1)[0].lower()
    return len(name) >= minimum and any(n.startswith(name) for n in names)


def dangerous(command: str) -> str | None:
    """Flag-aware detection of risky commands in any shell; returns a short description."""
    for words in _split(command):
        prog, args = words[0], words[1:]
        low = [a.lower() for a in args]
        if prog in _DELETE_PROGRAMS:
            for a, l in zip(args, low):
                if l in ("--recursive", "--force"):
                    return "recursive or forced delete"
                if prog == "rm" and re.fullmatch(r"-[a-zA-Z]+", a) and set(a[1:]) & set("rRf"):
                    return "recursive or forced delete"
                if l in ("/s", "/q", "/f"):  # cmd.exe del/rd
                    return "recursive or forced delete"
                if _ps_param(a, "recurse") or _ps_param(a, "force", minimum=2):
                    return "recursive or forced delete"
        if prog == "find":
            if "-delete" in low:
                return "recursive delete (find -delete)"
            for i, l in enumerate(low):
                if l in ("-exec", "-execdir", "-ok", "-okdir") and i + 1 < len(args):
                    inner = args[i + 1:]
                    if program(inner[0]) in _DELETE_PROGRAMS or dangerous(
                            " ".join(_requote(inner))):
                        return "recursive delete (find -exec)"
        if prog in ("chmod", "chown", "chgrp") and ({"-r", "--recursive"} & set(low)):
            return "recursive permission change"
        if prog in ("icacls", "cacls") and set(low) & {"/t", "/grant", "/deny", "/remove",
                                                       "/reset", "/setowner", "/grant:r"}:
            return "permission change"
        if prog in ("sudo", "su", "doas", "runas", "gsudo"):
            return "privilege elevation"
        if prog == "start-process" and "runas" in low:
            return "privilege elevation"
    return None


def pushes_to(command: str, branch: str) -> bool:
    """Whether a command pushes to (or deletes) `branch`, or pushes everything."""
    for words in _split(command):  # git global options are already stripped
        if words[0] != "git" or words[1:2] != ["push"]:
            continue
        rest = words[2:]
        if {"--all", "--mirror"} & set(rest):
            return True
        for w in rest:
            target = w.split(":")[-1].lstrip("+")
            if target in (branch, f"refs/heads/{branch}"):
                return True
    return False


def needs_approval(command: str, approval_prefixes: list[str]) -> str | None:
    """Why `command` needs approval (a matching prefix or a dangerous flag), or None."""
    hit = matches(command, approval_prefixes)
    if hit:
        return f"`{hit}`"
    reason = dangerous(command)
    return reason


# ---------------------------------------------------------------------- per-CLI files

def claude_settings(rules: dict[str, list[str]], cls: str) -> dict:
    def tools(prefixes):
        return [f"{tool}({p} *)" for p in prefixes for tool in ("Bash", "PowerShell")]

    perms = {"allow": ["mcp__plugin_hive_hive", "mcp__hive"] + tools(rules["allow"])}
    if cls == "orchestrator":  # interactive: dangerous commands ask the user
        perms["ask"] = tools(rules["approval"])
        perms["deny"] = tools(rules["forbidden"])
    else:  # headless: blocked here, run via request_approval instead
        perms["deny"] = tools(rules["forbidden"] + rules["approval"])
    return {"permissions": perms}


def gemini_policy(rules: dict[str, list[str]], cls: str) -> dict:
    """Policy rules as a dict for tomli_w ([[rule]] array of tables).

    Gemini CLI 0.41's validator requires `toolName` on every rule, even where its docs call
    `commandPrefix` / `mcpName` sufficient, so it is always set."""
    shell = "run_shell_command"
    rule = [{"mcpName": "hive", "toolName": "*", "decision": "allow", "priority": 800}]
    if rules["forbidden"]:
        rule.append({"toolName": shell, "commandPrefix": rules["forbidden"], "decision": "deny",
                     "priority": 950,
                     "denyMessage": "Hive never allows agents to run this command."})
    if rules["approval"]:
        if cls == "orchestrator":
            rule.append({"toolName": shell, "commandPrefix": rules["approval"],
                         "decision": "ask_user", "priority": 900})
        else:
            rule.append({"toolName": shell, "commandPrefix": rules["approval"],
                         "decision": "deny", "priority": 900,
                         "denyMessage": "This command needs the orchestrator's approval: call "
                                        "the hive request_approval tool with the exact command "
                                        "and your reason."})
    if rules["allow"]:
        rule.append({"toolName": shell, "commandPrefix": rules["allow"], "decision": "allow",
                     "priority": 500})
    return {"rule": rule}


def codex_rules(rules: dict[str, list[str]], cls: str) -> str:
    """Codex execpolicy rules (Starlark `prefix_rule` calls), copied into the slot's private
    CODEX_HOME/rules/ at launch. Codex applies the most restrictive matching decision. An
    `allow` rule also runs the command outside Codex's sandbox, like the other CLIs run it."""
    def rule(prefix: str, decision: str, why: str = "") -> str:
        pattern = ", ".join(json.dumps(w) for w in prefix.split())
        extra = f", justification = {json.dumps(why)}" if why else ""
        return f"prefix_rule(pattern = [{pattern}], decision = \"{decision}\"{extra})"

    lines = ["# Generated by `hive init` from hive.toml [permissions]; do not edit."]
    lines += [rule(p, "forbidden", "Hive never allows agents to run this command.")
              for p in rules["forbidden"]]
    if cls == "orchestrator":  # interactive: dangerous commands ask the user
        lines += [rule(p, "prompt") for p in rules["approval"]]
    else:
        lines += [rule(p, "forbidden", "This command needs the orchestrator's approval: call "
                                       "the hive request_approval tool with the exact command "
                                       "and your reason.") for p in rules["approval"]]
    lines += [rule(p, "allow") for p in rules["allow"]]
    return "\n".join(lines) + "\n"
